mapper.select:
SELECT h.yrt_id AS yrtId, e.emp_name AS empName, e.emp_no AS empNo, d.dept_name AS deptName, h.biz_place AS bizPlace FROM yrt_header h JOIN emp e ON e.emp_id = h.emp_id LEFT JOIN dept d ON d.dept_id = e.dept_id
AND h.base_year = #{baseYear}
AND h.biz_place = #{bizPlace}
AND d.dept_name LIKE '%' || #{deptName} || '%'
AND e.emp_name LIKE '%' || #{empName} || '%'
ORDER BY h.yrt_id
